{"content": "<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>طبقات الأرض — رحلة إلى مركز الكوكب</title>
<style>
  :root{
    --bg:#f7f5f1;
    --panel:#ffffff;
    --ink:#17181c;
    --muted:#6f6f78;
    --line:#e5e0d8;
    --crust:#8d6e63;
    --crust-2:#5d4037;
    --mantle:#c2410c;
    --mantle-2:#7c2d12;
    --outer:#f59e0b;
    --outer-2:#b45309;
    --inner:#fde68a;
    --inner-2:#f59e0b;
    --radius:16px;
    --sans:"Segoe UI",Tahoma,"Noto Naskh Arabic","Traditional Arabic","Geeza Pro",
           "Arial",sans-serif;
  }

  *{box-sizing:border-box}

  html{scroll-behavior:smooth}

  body{
    margin:0;
    background:var(--bg);
    color:var(--ink);
    font-family:var(--sans);
    line-height:1.9;
    -webkit-font-smoothing:antialiased;
  }

  #progress{
    position:fixed;top:0;right:0;height:3px;width:0%;
    background:linear-gradient(90deg,var(--inner),var(--outer),var(--mantle),var(--crust));
    z-index:100;transition:width .1s linear;
  }

  .wrap{max-width:1080px;margin:0 auto;padding:0 28px 100px}

  /* ---------- hero ---------- */
  header.hero{padding:104px 0 56px;text-align:center;border-bottom:1px solid var(--line)}
  .hero .eyebrow{
    font-size:12px;letter-spacing:.06em;color:var(--muted);margin-bottom:20px;
  }
  .hero h1{
    font-size:clamp(1.9rem,4.4vw,3rem);
    line-height:1.35;margin:0 0 .5em;font-weight:700;
  }
  .hero p{
    margin:0 auto;max-width:640px;color:var(--muted);font-size:16px;
  }
  .hero .meta{
    margin-top:30px;display:flex;justify-content:center;gap:28px;flex-wrap:wrap;
    font-size:13px;color:var(--muted);
  }
  .hero .meta b{color:var(--ink);font-weight:600}

  /* ---------- sections ---------- */
  section{padding:64px 0;border-bottom:1px solid var(--line);opacity:0;transform:translateY(18px);
    transition:opacity .7s ease,transform .7s ease}
  section.in{opacity:1;transform:none}

  .sec-head{margin-bottom:34px}
  .sec-head .num{
    font-size:11.5px;letter-spacing:.14em;color:var(--muted);
    display:block;margin-bottom:8px;
  }
  .sec-head h2{
    font-size:1.45rem;margin:0 0 8px;font-weight:700;
  }
  .sec-head p{margin:0;color:var(--muted);font-size:15px}

  /* ---------- diagram card ---------- */
  .stage{
    background:radial-gradient(120% 120% at 50% 0%,#1a2030 0%,#0c0f16 70%);
    border-radius:22px;
    padding:36px 24px 26px;
    box-shadow:0 24px 60px -30px rgba(12,15,22,.65);
  }
  .stage svg{display:block;width:100%;height:auto;max-width:560px;margin:0 auto}

  .ring{cursor:pointer;transition:opacity .3s ease,transform .3s ease;transform-origin:center}
  .ring.dim{opacity:.34}
  .ring.lit{filter:url(#glow)}

  .legend{
    display:grid;grid-template-columns:repeat(4,1fr);gap:10px;
    margin-top:26px;padding-top:22px;border-top:1px solid rgba(255,255,255,.1);
  }
  .legend button{
    all:unset;cursor:pointer;display:flex;align-items:center;gap:9px;
    padding:9px 10px;border-radius:10px;
    color:#cfd4e0;font-family:inherit;font-size:13.5px;line-height:1.4;
    transition:background .2s ease,color .2s ease;
  }
  .legend button:hover,.legend button:focus-visible{background:rgba(255,255,255,.07);color:#fff}
  .legend button.on{background:rgba(255,255,255,.12);color:#fff}
  .legend .dot{width:11px;height:11px;border-radius:3px;flex:0 0 auto}

  /* ---------- layer cards ---------- */
  .cards{display:grid;grid-template-columns:1fr 1fr;gap:18px}
  .card{
    background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);
    padding:26px 26px 24px;position:relative;overflow:hidden;
    transition:border-color .25s ease,box-shadow .25s ease,transform .25s ease;
  }
  .card::before{
    content:"";position:absolute;inset-inline-start:0;top:0;bottom:0;width:4px;
    background:var(--accent);
  }
  .card:hover,.card.hl{
    border-color:#d6cfc2;transform:translateY(-2px);
    box-shadow:0 16px 34px -24px rgba(23,24,28,.5);
  }
  .card h3{
    margin:0 0 4px;font-size:1.12rem;font-weight:700;display:flex;align-items:baseline;gap:8px;
  }
  .card .lat{font-size:12px;color:var(--muted);font-weight:400;letter-spacing:.04em}
  .card .depth{
    display:inline-block;margin:12px 0 16px;font-size:12.5px;color:#4b4b53;
    background:#f2efe9;border-radius:99px;padding:3px 12px;
  }
  .card ul{margin:0;padding-inline-start:18px}
  .card li{margin-bottom:9px;font-size:14.5px;color:#33343a}
  .card li:last-child{margin-bottom:0}
  .card li b{font-weight:650;color:var(--ink)}

  #card-crust{--accent:var(--crust)}
  #card-mantle{--accent:var(--mantle)}
  #card-outer{--accent:var(--outer)}
  #card-inner{--accent:var(--inner-2)}

  /* ---------- depth column ---------- */
  .column-wrap{
    display:grid;grid-template-columns:1.15fr .85fr;gap:40px;align-items:center;
  }
  .note{
    font-size:13px;color:var(--muted);margin-top:14px;
  }
  .facts{list-style:none;margin:0;padding:0}
  .facts li{
    padding:14px 0;border-bottom:1px dashed var(--line);
    display:flex;justify-content:space-between;gap:16px;font-size:14.5px;
  }
  .facts li:last-child{border-bottom:0}
  .facts .k{color:var(--muted)}
  .facts .v{font-weight:650;color:var(--ink);white-space:nowrap}

  /* ---------- seismic ---------- */
  .seismic{
    background:var(--panel);border:1px solid var(--line);border-radius:var(--radius);
    padding:30px 32px;
  }
  .seismic p{margin:0 0 14px;font-size:15px;color:#33343a}
  .seismic p:last-child{margin-bottom:0}
  .seismic .pill{
    display:inline-block;background:#fef3c7;color:#92400e;border-radius:6px;
    padding:1px 8px;font-size:13.5px;font-weight:600;
  }

  footer{padding:48px 0 0;text-align:center;font-size:13px;color:var(--muted)}

  @media (max-width:820px){
    .wrap{padding:0 18px 70px}
    .hero{padding:70px 0 44px}
    .cards{grid-template-columns:1fr}
    .column-wrap{grid-template-columns:1fr;gap:24px}
    .legend{grid-template-columns:1fr 1fr}
    .stage{padding:24px 14px 18px;border-radius:16px}
  }

  @media (prefers-reduced-motion:reduce){
    html{scroll-behavior:auto}
    section{opacity:1;transform:none;transition:none}
  }

  @media print{
    #progress{display:none}
    body{background:#fff}
    section{opacity:1;transform:none;break-inside:avoid}
    .stage{box-shadow:none}
  }
</style>
</head>
<body>

<div id="progress"></div>

<div class="wrap">

  <header class="hero">
    <div class="eyebrow">عرض تعليمي مبسّط</div>
    <h1>طبقات الأرض<br>رحلة إلى مركز الكوكب</h1>
    <p>ما الذي يوجد تحت أقدامنا؟ تنقسم الأرض إلى أربع طبقات رئيسية، تختلف في تركيبها وحالتها وحرارتها اختلافًا هائلًا.</p>
    <div class="meta">
      <span>نصف القطر: <b>6371 كم</b></span>
      <span>الحرارة في المركز: <b>≈ 5400 °م</b></span>
      <span>العمر: <b>≈ 4.5 مليار سنة</b></span>
    </div>
  </header>

  <!-- ============ 1. cutaway ============ -->
  <section id="s1">
    <div class="sec-head">
      <span class="num">01 — المقطع</span>
      <h2>مقطع عرضي في الأرض</h2>
      <p>اضغط على أي طبقة في الرسم أو في المفتاح أدناه لإبرازها.</p>
    </div>

    <div class="stage">
      <svg viewBox="0 0 560 560" role="img" aria-label="مقطع عرضي يوضح طبقات الأرض الأربع">
        <defs>
          <radialGradient id="gCrust" cx="35%" cy="28%" r="80%">
            <stop offset="0%" stop-color="#a1887f"/>
            <stop offset="100%" stop-color="#5d4037"/>
          </radialGradient>
          <radialGradient id="gMantle" cx="50%" cy="50%" r="62%">
            <stop offset="55%" stop-color="#7c2d12"/>
            <stop offset="100%" stop-color="#c2410c"/>
          </radialGradient>
          <radialGradient id="gOuter" cx="50%" cy="50%" r="60%">
            <stop offset="0%" stop-color="#b45309"/>
            <stop offset="100%" stop-color="#f59e0b"/>
          </radialGradient>
          <radialGradient id="gInner" cx="45%" cy="40%" r="65%">
            <stop offset="0%" stop-color="#fffbeb"/>
            <stop offset="100%" stop-color="#fbbf24"/>
          </radialGradient>
          <filter id="glow" x="-40%" y="-40%" width="180%" height="180%">
            <feGaussianBlur stdDeviation="7" result="b"/>
            <feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
          </filter>
        </defs>

        <!-- planet -->
        <circle cx="280" cy="280" r="212" fill="url(#gCrust)"/>
        <circle class="ring" data-layer="mantle" cx="280" cy="280" r="209" fill="url(#gMantle)"/>
        <circle class="ring" data-layer="outer"  cx="280" cy="280" r="171" fill="url(#gOuter)"/>
        <circle class="ring" data-layer="inner"  cx="280" cy="280" r="40"  fill="url(#gInner)" filter="url(#glow)"/>

        <!-- thin highlight on crust edge so it stays visible -->
        <circle class="ring" data-layer="crust" cx="280" cy="280" r="212"
                fill="none" stroke="#4e342e" stroke-width="3"/>

        <!-- subtle boundary hairlines -->
        <circle cx="280" cy="280" r="209" fill="none" stroke="rgba(0,0,0,.25)" stroke-width="1"/>
        <circle cx="280" cy="280" r="171" fill="none" stroke="rgba(0,0,0,.25)" stroke-width="1"/>

        <!-- surface hint: equator-ish arcs -->
        <ellipse cx="280" cy="280" rx="212" ry="34" fill="none"
                 stroke="rgba(255,255,255,.10)" stroke-width="1"/>
        <ellipse cx="280" cy="280" rx="34" ry="212" fill="none"
                 stroke="rgba(255,255,255,.10)" stroke-width="1"/>
      </svg>

      <div class="legend">
        <button data-layer="crust" type="button">
          <span class="dot" style="background:linear-gradient(135deg,#a1887f,#5d4037)"></span>
          <span>القشرة</span>
        </button>
        <button data-layer="mantle" type="button">
          <span class="dot" style="background:linear-gradient(135deg,#c2410c,#7c2d12)"></span>
          <span>الوشاح</span>
        </button>
        <button data-layer="outer" type="button">
          <span class="dot" style="background:linear-gradient(135deg,#f59e0b,#b45309)"></span>
          <span>اللب الخارجي</span>
        </button>
        <button data-layer="inner" type="button">
          <span class="dot" style="background:linear-gradient(135deg,#fffbeb,#fbbf24)"></span>
          <span>اللب الداخلي</span>
        </button>
      </div>
    </div>
  </section>

  <!-- ============ 2. cards ============ -->
  <section id="s2">
    <div class="sec-head">
      <span class="num">02 — الطبقة تلو الطبقة</span>
      <h2>الأربع طبقات بالتفصيل</h2>
      <p>من السطح إلى المركز، يزداد الضغط والحرارة باستمرار.</p>
    </div>

    <div class="cards">

      <article class="card" id="card-crust" data-layer="crust">
        <h3>القشرة <span class="lat">Crust</span></h3>
        <div class="depth">من السطح إلى 70 كم</div>
        <ul>
          <li><b>الحالة:</b> صلبة وهشّة، تتصدّع وتنكسر.</li>
          <li><b>التركيب:</b> صخور سيليكاتية — غرانيت في القارات وبازلت في قاع المحيطات.</li>
          <li><b>الحرارة:</b> من حرارة الجو إلى نحو 400 °م في القاعدة.</li>
          <li><b>ملاحظة:</b> أرقّ طبقة على الإطلاق، وتشكّل أقل من 1% من حجم الأرض.</li>
        </ul>
      </article>

      <article class="card" id="card-mantle" data-layer="mantle">
        <h3>الوشاح <span class="lat">Mantle</span></h3>
        <div class="depth">من 70 إلى 2900 كم</div>
        <ul>
          <li><b>الحالة:</b> صلب، لكنه يتحرّك ببطء شديد على مدى ملايين السنين.</li>
          <li><b>التركيب:</b> سيليكات غنية بالمغنيسيوم والحديد، أهمها البيريدوتيت.</li>
          <li><b>الحرارة:</b> بين 500 و3700 °م تقريبًا.</li>
          <li><b>ملاحظة:</b> تيارات الحمل الحراري فيه هي المحرّك الذي يحرّك الصفائح التكتونية.</li>
        </ul>
      </article>

      <article class="card" id="card-outer" data-layer="outer">
        <h3>اللب الخارجي <span class="lat">Outer Core</span></h3>
        <div class="depth">من 2900 إلى 5150 كم</div>
        <ul>
          <li><b>الحالة:</b> سائل منصهر بالكامل.</li>
          <li><b>التركيب:</b> حديد ونيكل، مع كميات ضئيلة من عناصر أخف.</li>
          <li><b>الحرارة:</b> بين 4400 و5000 °م.</li>
          <li><b>ملاحظة:</b> دورانه وتياراته الكهربائية يولّدان المجال المغناطيسي للأرض.</li>
        </ul>
      </article>

      <article class="card" id="card-inner" data-layer="inner">
        <h3>اللب الداخلي <span class="lat">Inner Core</span></h3>
        <div class="depth">من 5150 إلى 6371 كم</div>
        <ul>
          <li><b>الحالة:</b> صلب رغم الحرارة الهائلة، بفعل الضغط الشديد.</li>
          <li><b>التركيب:</b> حديد ونيكل بشكل أساسي.</li>
          <li><b>الحرارة:</b> نحو 5400 °م، قريبة من حرارة سطح الشمس.</li>
          <li><b>ملاحظة:</b> ينمو ببطء عبر الزمن مع تجمّد الحديد عند حدود الوشاح.</li>
        </ul>
      </article>

    </div>
  </section>

  <!-- ============ 3. depths ============ -->
  <section id="s3">
    <div class="sec-head">
      <span class="num">03 — الأعماق</span>
      <h2>حدود الطبقات على مسار العمق</h2>
      <p>كلما نزلنا، زاد الضغط والحرارة، وتغيّرت حالة المادة.</p>
    </div>

    <div class="column-wrap">
      <div>
        <svg viewBox="0 0 560 470" role="img" aria-label="عمود يوضح حدود الطبقات وأعماقها">
          <g font-family="Segoe UI, Tahoma, sans-serif">
            <!-- bars -->
            <rect x="255" y="20"  width="120" height="34"  rx="4" fill="url(#gCrust)"/>
            <rect x="255" y="56"  width="120" height="162" rx="4" fill="url(#gMantle)"/>
            <rect x="255" y="220" width="120" height="124" rx="4" fill="url(#gOuter)"/>
            <rect x="255" y="346" width="120" height="100" rx="4" fill="url(#gInner)"/>

            <!-- layer names (right side) -->
            <text x="415" y="42"  text-anchor="middle" font-size="15" font-weight="600" fill="#17181c">القشرة</text>
            <text x="415" y="142" text-anchor="middle" font-size="15" font-weight="600" fill="#17181c">الوشاح</text>
            <text x="415" y="288" text-anchor="middle" font-size="15" font-weight="600" fill="#17181c">اللب الخارجي</text>
