(function () {
  "use strict";

  /* ---------- scroll progress ---------- */
  var bar = document.getElementById("progress");
  function onScroll() {
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    bar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + "%";
  }
  window.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", onScroll);
  onScroll();

  /* ---------- reveal ---------- */
  var sections = [].slice.call(document.querySelectorAll("section"));
  if ("IntersectionObserver" in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
      });
    }, { threshold: 0.1 });
    sections.forEach(function (s) { io.observe(s); });
  } else {
    sections.forEach(function (s) { s.classList.add("in"); });
  }

  /* ---------- layer highlighting ---------- */
  var rings = [].slice.call(document.querySelectorAll(".ring"));
  var cards = [].slice.call(document.querySelectorAll(".card"));
  var buttons = [].slice.call(document.querySelectorAll(".legend button"));
  var current = null;

  function clear() {
    rings.forEach(function (r) { r.classList.remove("dim", "lit"); });
    cards.forEach(function (c) { c.classList.remove("hl"); });
    buttons.forEach(function (b) { b.classList.remove("on"); });
  }

  function highlight(layer) {
    clear();
    if (!layer || layer === current) { current = null; return; }
    current = layer;
    rings.forEach(function (r) {
      var match = r.getAttribute("data-layer") === layer;
      r.classList.toggle("lit", match);
      r.classList.toggle("dim", !match);
    });
    cards.forEach(function (c) {
      c.classList.toggle("hl", c.getAttribute("data-layer") === layer);
    });
    buttons.forEach(function (b) {
      b.classList.toggle("on", b.getAttribute("data-layer") === layer);
    });
  }

  function focusLayer(layer, scroll) {
    highlight(layer);
    if (scroll) {
      var card = document.getElementById("card-" + layer);
      if (card) card.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  }

  buttons.forEach(function (b) {
    b.addEventListener("click", function () {
      focusLayer(b.getAttribute("data-layer"), true);
    });
  });

  rings.forEach(function (r) {
    r.addEventListener("click", function () {
      focusLayer(r.getAttribute("data-layer"), true);
    });
    r.addEventListener("mouseenter", function () {
      if (!current) highlight(r.getAttribute("data-layer"));
    });
    r.addEventListener("mouseleave", function () {
      if (!current) highlight(null);
    });
  });

  cards.forEach(function (c) {
    c.addEventListener("mouseenter", function () {
      if (!current) highlight(c.getAttribute("data-layer"));
    });
    c.addEventListener("mouseleave", function () {
      if (!current) highlight(null);
    });
  });

  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") { current = null; clear(); }
  });
})();
