{"path": "/home/agent/workspace/top_customers.py", "content": """"Rank customers by net spend (orders paid, minus refunds) and write top-cust.csv."""

import csv
from decimal import Decimal, ROUND_HALF_UP

INPUT = "bookstore_orders.csv"
OUTPUT = "top-cust.csv"
TOP_N = 10

spend = {}  # customer_id -> [full_name, net_spend]

with open(INPUT, newline="", encoding="utf-8-sig") as f:
    for row in csv.DictReader(f):
        # Declined orders and cancellations produced no money spent.
        if row["payment_status"].strip().lower() != "paid":
            continue
        if row["fulfillment_status"].strip().lower() == "cancelled":
            continue

        cid = row["customer_id"].strip()
        name = " ".join(
            part.strip()
            for part in (row["customer_first_name"], row["customer_last_name"])
            if part.strip()
        )
        net = Decimal(row["order_grand_total"]) - Decimal(row["refund_amount"])

        if cid not in spend:
            spend[cid] = [name, Decimal("0")]
        spend[cid][1] += net

ranked = sorted(spend.items(), key=lambda kv: kv[1][1], reverse=True)[:TOP_N]

with open(OUTPUT, "w", newline="", encoding="utf-8") as f:
    writer = csv.writer(f)
    writer.writerow(["FullName", "TotalSpend"])
    for _, (name, total) in ranked:
        writer.writerow([name, str(total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))])

for i, (cid, (name, total)) in enumerate(ranked, 1):
    print(f"{i:>2}. {cid:<10} {name:<22} {total.quantize(Decimal('0.01'))}")"}

