fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "Auto"

    val seconds = exposureTimeNs / NANOS_PER_SECOND

    if (seconds >= 1.0) {
        val tenthsOfSecond = (seconds * 10.0).roundToLong()
        return if (tenthsOfSecond % 10L == 0L) {
            "${tenthsOfSecond / 10L}s"
        } else {
            String.format(Locale.US, "%.1fs", seconds)
        }
    }

    val denominator = (1.0 / seconds).roundToLong().coerceAtLeast(1L)
    return "1/${denominator}s"
}

fun processCaptureInBackground(
    context: Context,
    byteBuffer: ByteBuffer,
    width: Int,
    height: Int,
    timestamp: Long,
    readbackTime: Long,
    shutterStartTime: Long,
    metadata: CaptureMetadata
) {
    try {
        val bitmapStart = System.currentTimeMillis()
        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        byteBuffer.rewind()
        bitmap.copyPixelsFromBuffer(byteBuffer)
        val bitmapEnd = System.currentTimeMillis()

        saveBitmapToGallery(context, bitmap, metadata, shutterStartTime, readbackTime, bitmapEnd - bitmapStart)
        bitmap.recycle()

        val end = System.currentTimeMillis()
        Log.d(
            TAG,
            "[PERF_CAPTURE] res=${width}x${height} total=${end - shutterStartTime}ms " +
                "wait=${bitmapStart - shutterStartTime}ms copy=${bitmapEnd - bitmapStart}ms " +
                "write=${end - bitmapEnd}ms readback=${readbackTime}ms"
        )
    } catch (e: Exception) {
        Log.e(TAG, "capture Background capture failed: ${e.message}", e)
    }
}

fun saveBitmapToGallery(
    context: Context,
    bitmap: Bitmap,

