    metadata: CaptureMetadata,
    shutterStart: Long,
    readbackTime: Long,
    bitmapTime: Long
) {
    val now = System.currentTimeMillis()
    val contentValues = ContentValues().apply {
        put(MediaStore.MediaColumns.DISPLAY_NAME, "LATENT_${metadata.timestamp}.jpg")
        put(MediaStore.MediaColumns.MIME_TYPE, MIME_TYPE_JPEG)
        put(MediaStore.MediaColumns.RELATIVE_PATH, GALLERY_RELATIVE_PATH)
        put(MediaStore.MediaColumns.DATE_TAKEN, metadata.timestamp)
        put(MediaStore.MediaColumns.DATE_ADDED, now / 1000)
        put(MediaStore.MediaColumns.DATE_MODIFIED, now / 1000)
        put(MediaStore.MediaColumns.WIDTH, bitmap.width)
        put(MediaStore.MediaColumns.HEIGHT, bitmap.height)
        put(MediaStore.Images.ImageColumns.ORIENTATION, 0)
        put(MediaStore.MediaColumns.IS_PENDING, 1)
    }

    val imageUri = context.contentResolver
        .insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, contentValues)
        ?: return

    try {
        val encodeStart = System.currentTimeMillis()
        context.contentResolver.openOutputStream(imageUri)?.use { outputStream ->
            bitmap.compress(Bitmap.CompressFormat.JPEG, JPEG_QUALITY, outputStream)
        }
        val encodeEnd = System.currentTimeMillis()

        writeExifMetadata(context, imageUri, metadata)
        val exifEnd = System.currentTimeMillis()

        context.contentResolver.update(
            imageUri,
            ContentValues().apply { put(MediaStore.MediaColumns.IS_PENDING, 0) },
            null,
            null
        )

        if (BuildConfig.DEBUG) {
            Log.d(
                TAG,
                "[PERF_STILL] total=${exifEnd - shutterStart}ms readback=${readbackTime}ms " +
                    "bitmap=${bitmapTime}ms encode=${encodeEnd - encodeStart}ms exif=${exifEnd - encodeEnd}ms"
            )
        }
    } catch (e: Exception) {
        Log.e(TAG, "capture Failed to save image or metadata", e)
        context.mainExecutor.execute {
            Toast.makeText(context, "Failed to save image", Toast.LENGTH_SHORT).show()
        }
    }
}

private fun writeExifMetadata(context: Context, imageUri: Uri, metadata: CaptureMetadata) {
    context.contentResolver.openFileDescriptor(imageUri, "rw")?.use { descriptor ->
        val exif = ExifInterface(descriptor.fileDescriptor)
        val exposureSeconds = if (metadata.exposureTimeNs > 0) {
            metadata.exposureTimeNs / NANOS_PER_SECOND
        } else {
            0.0
        }

        exif.setAttribute(ExifInterface.TAG_MAKE, metadata.make)
        exif.setAttribute(ExifInterface.TAG_MODEL, metadata.model)
        exif.setAttribute(ExifInterface.TAG_SOFTWARE, "Latent Camera")
        exif.setAttribute(ExifInterface.TAG_ARTIST, "Latent Camera")
        exif.setAttribute(ExifInterface.TAG_FOCAL_LENGTH, "${(metadata.focalLength * 1000).toInt()}/1000")
        exif.setAttribute(ExifInterface.TAG_F_NUMBER, metadata.aperture.toString())
        exif.setAttribute(ExifInterface.TAG_PHOTOGRAPHIC_SENSITIVITY, metadata.iso.toString())

        Log.d(
            TAG,
            "Writing EXIF: ISO=${metadata.iso}, Exp=${exposureSeconds}s, " +
                "Focal=${metadata.focalLength}, Aperture=${metadata.aperture}, Location=${metadata.location}"
        )

        exif.setAttribute(ExifInterface.TAG_EXPOSURE_TIME, exposureSeconds.toString())

        metadata.location?.let { location: Location ->
            exif.setLatLong(location.latitude, location.longitude)
            exif.setGpsInfo(location)
        }

        exif.saveAttributes()
    }
}

@Composable
fun BuildTimerText(modifier: Modifier = Modifier) {
    var buildTimeText by remember { mutableStateOf("Built: calculating...") }

    LaunchedEffect(Unit) {
        while (true) {
            val diffMs = System.currentTimeMillis() - BuildConfig.BUILD_TIME
            val diffMin = diffMs / (1000 * 60)
            buildTimeText = if (diffMin < 1) "Built: just now" else "Built: $diffMin min ago"
            delay(BUILD_TIMER_REFRESH_MS)
        }
    }

    Surface(
        modifier = modifier,
        color = Color.Black.copy(alpha = 0.5f),
        shape = CircleShape
    ) {
        Text(
            text = buildTimeText,
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp),
            color = Color.White,
            style = MaterialTheme.typography.labelMedium
        )
    }
}

