    white = side == "w"
    home_row = 7 if white else 0
    king = "K" if white else "k"
    rook = "R" if white else "r"
    king_right = "K" if white else "k"
    queen_right = "Q" if white else "q"

    if board[home_row][4] != king:
        return
    if _square_attacked(board, home_row, 4, by_white=not white):
        return

    # King side: f- and g-files must be clear, and f/g must not be attacked.
    if king_right in castling_rights:
        if (
            board[home_row][7] == rook
            and board[home_row][5] is None
            and board[home_row][6] is None
            and not _square_attacked(board, home_row, 5, by_white=not white)
            and not _square_attacked(board, home_row, 6, by_white=not white)
        ):
            _add_move(moves, home_row, 4, home_row, 6)

    # Queen side: b-, c-, and d-files must be clear; c/d must not be attacked.
    if queen_right in castling_rights:
        if (
            board[home_row][0] == rook
            and board[home_row][1] is None
            and board[home_row][2] is None
            and board[home_row][3] is None
            and not _square_attacked(board, home_row, 3, by_white=not white)
            and not _square_attacked(board, home_row, 2, by_white=not white)
        ):
