def _apply_move(
    board: list[list[str | None]], move: str
) -> list[list[str | None]]:
    """Return a new board with the UCI move applied."""
    fc = FILES.index(move[0])
    fr = 8 - int(move[1])
    tc = FILES.index(move[2])
    tr = 8 - int(move[3])

    new_board = [row[:] for row in board]
    piece = new_board[fr][fc]
    new_board[fr][fc] = None
    new_board[tr][tc] = piece

    # Castling also moves the rook to the far side of the king.
    if piece is not None and piece.upper() == "K" and abs(tc - fc) == 2:
        rook_from = 7 if tc > fc else 0
        rook_to = 5 if tc > fc else 3
        new_board[fr][rook_to] = new_board[fr][rook_from]
        new_board[fr][rook_from] = None

    return new_board


def _rook_right(piece: str, row: int, col: int) -> str:
    if piece == "R":
        if (row, col) == (7, 7):
            return "K"
        if (row, col) == (7, 0):
            return "Q"
    else:
        if (row, col) == (0, 7):
            return "k"
        if (row, col) == (0, 0):
            return "q"
    return ""


def _update_castling_rights(
    castling_rights: str,
    board: list[list[str | None]],
    move: str,
) -> str:
    """Update castling rights after a move (king/rook move or rook capture)."""
    fr = 8 - int(move[1])
    fc = FILES.index(move[0])
    tr = 8 - int(move[3])
    tc = FILES.index(move[2])
    removed = ""

    piece = board[fr][fc]
    if piece == "K":
        removed += "KQ"
    elif piece == "k":
        removed += "kq"
    elif piece is not None and piece.upper() == "R":
        removed += _rook_right(piece, fr, fc)

    captured = board[tr][tc]
    if captured is not None and captured.upper() == "R":
        removed += _rook_right(captured, tr, tc)

    return "".join(right for right in castling_rights if right not in removed)


def perft(fen: str, depth: int) -> int:
    """Count leaf nodes of the pseudo-legal move tree at the given depth."""
    if depth < 0:
        raise ValueError("depth must be non-negative")
    if depth == 0:
        return 1

    board, side, castling_rights = _parse_fen(fen)
    moves = legal_moves(fen)
    if depth == 1:
        return len(moves)

    total = 0
    next_side = "b" if side == "w" else "w"
    for move in moves:
        new_board = _apply_move(board, move)
        new_rights = _update_castling_rights(castling_rights, board, move)
        # Rebuild a FEN for the child position. Castling rights are preserved
        # when the king/rook have not moved and no rook was captured.
        rows = []
        for row in new_board:
            empty = 0
            rank = []
            for square in row:
                if square is None:
                    empty += 1
                else:
                    if empty:
                        rank.append(str(empty))
                        empty = 0
                    rank.append(square)
            if empty:
                rank.append(str(empty))
            rows.append("".join(rank))
        rights_field = new_rights or "-"
        child_fen = f"{'/'.join(rows)} {next_side} {rights_field} - 0 1"
        total += perft(child_fen, depth - 1)

    return total

