    moves.append(_square_name(fr, fc) + _square_name(tr, tc))


def _generate_pawn_moves(
    board: list[list[str | None]],
    row: int,
    col: int,
    piece: str,
    moves: list[str],
) -> None:
    white = _is_white(piece)
    direction = -1 if white else 1
    start_row = 6 if white else 1

    one_row = row + direction
    if _on_board(one_row, col) and board[one_row][col] is None:
        _add_move(moves, row, col, one_row, col)

        two_row = row + 2 * direction
        if row == start_row and board[two_row][col] is None:
